rows=json.loads((OUT/'maps_D_independent_audit.json').read_text())
runs=json.loads((OUT/'maps_D_program_runs.json').read_text())
for row in rows:
    if not row['source_id'].startswith('D.2.'):continue
    n=int(row['source_id'].split('.')[-1])
    if n not in notes:continue
    row['own_check'].update(proof_read='whole source statement and complete proof, including every concluding derivation',details=notes[n],
      outcome='complete proof checked; no gap found under stated hypotheses' if n in verified else 'complete proof read and rederived; exact outstanding closure steps identified in details',
      source_candidate_comparison='Every mathematical paragraph is preserved in the complete extracted source block; no silent weakening.')
    row['check_outcome']='verified complete proof under stated hypotheses' if n in verified else 'complete proof read; scoped closure tasks pending'
    if n==4:row['check_outcome']='historical open/problem block read; current open claims to be reconciled with later checked results'
    if n==2:row['check_outcome']='bounded archival computation read; fresh engine rerun timed out'
    row['program_runs']=[r for r in runs if Path(r['program']).stem in program_names.get(n,[])]
    s=(ROOT/'deliverables'/row['extracted_file']).read_text()
    refs=[]
    for group in re.findall(r'\\cite(?:\[[^\]]*\])*\{([^}]+)\}',s):refs.extend(group.split(','))
    row['reference_dependencies']=sorted(set(refs))
    if n==1:row['editorial_changes']=['Correct manFukae02 author to Mitsuaki Fukae, verified on original title page.']
(OUT/'maps_D_independent_audit.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
with (OUT/'maps_D_independent_audit.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['source_id','source_title','check_outcome','printed_label','extracted_file','details']);w.writeheader()
 for r in rows:w.writerow({k:r.get(k,'') for k in w.fieldnames if k!='details'}|{'details':r['own_check'].get('details','')})
